"""Apply reviewed screenshot stream patch, preserving all earlier source-root repairs."""
import base64,gzip,hashlib,subprocess
DATA=""
p=gzip.decompress(base64.b64decode(DATA))
assert hashlib.sha256(p).hexdigest()=='b14e648068f53b23266ee757afebeeb00a17777e2cf15e4978a09b9511a15ece'
subprocess.run(['git','apply','--check','-'],input=p,check=True)
subprocess.run(['git','apply','-'],input=p,check=True)
